// A developer's workaround for testing a refund-handling code path:
// hand-write a JSON object shaped like what they *think*
// a refund.created event looks like, based on the docs, and
// POST it directly to their local endpoint with curl — no
// signature header included, since "it's just local testing."

async function deliverWithRetry(notification, maxAttempts = 3) {
  for (let i = 0; i < maxAttempts; i++) {
    try {
      await fetch(notification.webhookUrl, {
        method: 'POST',
        body: JSON.stringify(notification.payload),
      });
      return; // assume success if no exception thrown
    } catch (err) {
      await sleep(1000);
    }
  }
}

